/**
 * Threat Risk Scoring Engine
 *
 * Computes a composite AI risk score (0–100) from five independent signal
 * categories, each normalised to [0, 100] before weighting.
 *
 * Weights
 * ─────────────────────────────────────────────
 *  Severity              25 %   (alert severity level)
 *  Correlation           20 %   (number of correlated events)
 *  Threat Intelligence   25 %   (known IOC / TI feed match confidence)
 *  Behavioural Anomaly   20 %   (deviation score from baseline behaviour)
 *  MITRE ATT&CK Match    10 %   (number of matched ATT&CK techniques)
 * ─────────────────────────────────────────────
 *  Total                100 %
 *
 * Classification bands
 * ─────────────────────────────────────────────
 *   0 – 30   LOW
 *  31 – 60   MEDIUM
 *  61 – 80   HIGH
 *  81 – 100  CRITICAL
 */

export type SeverityLevel = "LOW" | "MEDIUM" | "HIGH" | "CRITICAL";

export type RiskClassification = "LOW" | "MEDIUM" | "HIGH" | "CRITICAL";

export interface RiskInputs {
  /** Alert severity level reported by the detection source */
  severity: SeverityLevel;

  /**
   * Raw count of events correlated to this alert across all sensors/sources.
   * Capped internally at 40 for normalisation.
   */
  correlatedEvents: number;

  /**
   * Threat-intelligence match confidence: 0–100.
   * 0 = no match in any TI feed; 100 = confirmed IOC hit with high confidence.
   */
  tiMatchScore: number;

  /**
   * Behavioural anomaly score: 0–100.
   * Derived from deviation from a device's rolling baseline (e.g. z-score mapped to 0-100).
   */
  behaviourScore: number;

  /**
   * Number of distinct MITRE ATT&CK (ICS) techniques matched.
   * Capped internally at 5 for normalisation.
   */
  mitreMatchCount: number;
}

export interface RiskScoreResult {
  /** Final composite score, rounded to the nearest integer, clamped [0, 100] */
  score: number;
  /** Tier classification based on score bands */
  classification: RiskClassification;
  /** Per-factor breakdown for transparency / tooltip display */
  breakdown: {
    severityScore: number;
    correlationScore: number;
    tiScore: number;
    behaviourScore: number;
    mitreScore: number;
  };
}

// ── Weights (must sum to 1.0) ──────────────────────────────────────────────
const W_SEVERITY    = 0.25;
const W_CORRELATION = 0.20;
const W_TI          = 0.25;
const W_BEHAVIOUR   = 0.20;
const W_MITRE       = 0.10;

/** Map a severity label to a normalised 0–100 value. */
function normaliseSeverity(s: SeverityLevel): number {
  const map: Record<SeverityLevel, number> = {
    LOW:      20,
    MEDIUM:   50,
    HIGH:     80,
    CRITICAL: 100,
  };
  return map[s] ?? 20;
}

/** Normalise a raw event count to 0–100, capped at maxEvents. */
function normaliseCount(count: number, max: number): number {
  return Math.min(100, (count / max) * 100);
}

/** Classify a score into a named risk tier. */
function classify(score: number): RiskClassification {
  if (score >= 81) return "CRITICAL";
  if (score >= 61) return "HIGH";
  if (score >= 31) return "MEDIUM";
  return "LOW";
}

/**
 * Compute the composite threat risk score from raw signal inputs.
 */
export function computeRiskScore(inputs: RiskInputs): RiskScoreResult {
  const severityScore    = normaliseSeverity(inputs.severity);
  const correlationScore = normaliseCount(inputs.correlatedEvents, 40);
  const tiScore          = Math.min(100, Math.max(0, inputs.tiMatchScore));
  const behaviourScore   = Math.min(100, Math.max(0, inputs.behaviourScore));
  const mitreScore       = normaliseCount(inputs.mitreMatchCount, 5);

  const raw =
    severityScore    * W_SEVERITY    +
    correlationScore * W_CORRELATION +
    tiScore          * W_TI          +
    behaviourScore   * W_BEHAVIOUR   +
    mitreScore       * W_MITRE;

  const score = Math.min(100, Math.max(0, Math.round(raw)));

  return {
    score,
    classification: classify(score),
    breakdown: { severityScore, correlationScore, tiScore, behaviourScore, mitreScore },
  };
}

