function classify(score: number): RiskClassification {
  if (score >= 81) return "CRITICAL";
  if (score >= 61) return "HIGH";
  if (score >= 31) return "MEDIUM";
  return "LOW";
}

/**
 * Compute the composite threat risk score from raw signal inputs.
 */
export function computeRiskScore(inputs: RiskInputs): RiskScoreResult {
  const severityScore    = normaliseSeverity(inputs.severity);
  const correlationScore = normaliseCount(inputs.correlatedEvents, 40);
  const tiScore          = Math.min(100, Math.max(0, inputs.tiMatchScore));
  const behaviourScore   = Math.min(100, Math.max(0, inputs.behaviourScore));
  const mitreScore       = normaliseCount(inputs.mitreMatchCount, 5);

  const raw =
    severityScore    * W_SEVERITY    +
    correlationScore * W_CORRELATION +
    tiScore          * W_TI          +
    behaviourScore   * W_BEHAVIOUR   +
    mitreScore       * W_MITRE;

  const score = Math.min(100, Math.max(0, Math.round(raw)));

  return {
    score,
    classification: classify(score),
    anomalyStatus: behaviourScore > ANOMALY_THRESHOLD ? "suspicious" : "normal",
    breakdown: { severityScore, correlationScore, tiScore, behaviourScore, mitreScore },
  };
}

